static void init(const unsigned char*record,const RTFrame old[2]){memset(&m,0,sizeof m);m.cr=0x31;for(unsigned i=0;i<262144;++i)m.mem[i]=UINT32_MAX;for(unsigned i=0;i<32768;++i)m.mem[0xA0000/4+i]=0;for(unsigned c=0;c<2;++c){uint32_t base=layout.core[c][0].base;store(base-32,old[c].bytes+12,608);store(base+2048,old[c].bytes+620,64);}store(0x080C0000,record,128);}


